const STORAGE_KEY='jarvis-v499-live-data',ATT_KEY='jarvis-v499-attendance';let DATA=null,editing=false,ATT=[];
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])),yen=n=>'¥'+Math.round(Number(n)||0).toLocaleString('ja-JP');
function go(page){document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.nav-item').forEach(x=>x.classList.remove('active'));$('page-'+page)?.classList.add('active');document.querySelector(`[data-page="${page}"]`)?.classList.add('active');$('pageTitle').textContent=meta[page][0];$('pageSub').textContent=meta[page][1];closeMenu();if(page==='drivers')renderDrivers();if(page==='shiftboard'){renderShiftMatrix();renderAreaDrivers();renderDelivery();}if(page==='workbook')renderWorkbook()}
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));const menu=$('sideMenu'),overlay=$('overlay');function openMenu(){menu?.classList.add('open');overlay?.classList.add('show')}function closeMenu(){menu?.classList.remove('open');overlay?.classList.remove('show')}$('openMenu')?.addEventListener('click',openMenu);$('closeMenu')?.addEventListener('click',closeMenu);overlay?.addEventListener('click',closeMenu);
function normName(s){return String(s||'').replace(/\u3000/g,' ').replace(/\s+/g,' ').trim()}
function canonicalDriverName(s){const n=normName(s).replace(/\s/g,'');if(n==='津田'||n==='津田たけし')return '津田 たけし';if(n==='島田'||n==='島田真一')return '島田 真一';return s}
function cleanAttendance(xs){const excluded=new Set(['芹澤由承','遠藤栞音','安曇知晃','小田']);const out=[],pos=new Map();(Array.isArray(xs)?xs:[]).forEach(a=>{if(excluded.has(normName(a.driver).replace(/\s/g,'')))return;const r={...a,driver:canonicalDriverName(a.driver)};const k=`${r.date}|${normName(r.driver)}`;if(!pos.has(k)){pos.set(k,out.length);out.push(r);return}const i=pos.get(k),old=out[i];if(!old.source&&r.source)return;if(old.source&&!r.source){out[i]=r;return}if(String(old.source||'').startsWith('2026-08-shift')&&String(r.source||'').startsWith('2026-08-shift'))out[i]=r});return out}
function driverAreas(d){return d.areas||[d.area]}
function legacyAttendance(){
  const keys=['jarvis-v498-attendance','jarvis-v497-attendance','jarvis-v496-attendance','jarvis-v495-attendance','jarvis-v494-attendance','jarvis-v493-attendance','jarvis-v492-attendance','jarvis-v491-attendance','jarvis-v485-attendance','jarvis-v475-attendance','jarvis-v472-attendance','jarvis-v471-attendance','jarvis-v47-attendance','jarvis-v46-attendance','jarvis-v45-attendance'];
  const out=[],seen=new Set();
  keys.forEach(k=>{try{const xs=JSON.parse(localStorage.getItem(k)||'[]');(Array.isArray(xs)?xs:[]).forEach(a=>{const id=`${a.date}|${normName(a.driver)}`;if(!seen.has(id)){out.push(a);seen.add(id)}})}catch{}});
  return out;
}
function seedAugustShift(){
  let changed=false;
  const latestKeys=new Set(AUGUST_SHIFT_SEED.map(s=>`${s.date}|${normName(s.driver)}`));
  const before=ATT.length;
  ATT=ATT.filter(a=>!(String(a.source||'').startsWith('2026-08-shift')&&String(a.date||'').startsWith('2026-08')&&!latestKeys.has(`${a.date}|${normName(a.driver)}`)));
  if(ATT.length!==before)changed=true;
  AUGUST_SHIFT_SEED.forEach(s=>{
    const idx=ATT.findIndex(a=>a.date===s.date&&normName(a.driver)===normName(s.driver));
    if(idx<0){ATT.push({...s});changed=true;return}
    if(String(ATT[idx].source||'').startsWith('2026-08-shift')){ATT[idx]={...s};changed=true}
  });
  if(changed)localStorage.setItem(ATT_KEY,JSON.stringify(ATT));
}
function today(){return DATA?.data_date||new Date().toISOString().slice(0,10)}
function attendanceFor(date=today()){return ATT.filter(a=>a.date===date)}
function driverMonthDays(d){const days=new Set(ATT.filter(a=>normName(a.driver)===normName(d.name)&&a.status==='出勤'&&a.date.startsWith('2026-08')).map(a=>a.date));return days.size}
function areaToday(area){return attendanceFor().filter(a=>a.area===area&&a.status==='出勤')}
function populateForm(){const areas=Object.keys(AREA_PROJECTS);if($('attArea'))$('attArea').innerHTML=areas.map(a=>`<option>${a}</option>`).join('');if($('driverAreaFilter'))$('driverAreaFilter').innerHTML='<option value="all">全エリア</option>'+areas.map(a=>`<option>${a}</option>`).join('');if($('attDate'))$('attDate').value=today();if($('attArea')&&$('attDriver')&&$('attProject'))updateDriverProject();}
function updateDriverProject(){if(!$('attArea')||!$('attDriver')||!$('attProject'))return;const area=$('attArea').value;$('attDriver').innerHTML=DRIVERS.filter(d=>driverAreas(d).includes(area)).map(d=>`<option>${esc(d.name)}</option>`).join('')+`<option value="__new__">＋新しいドライバー</option>`;$('attProject').innerHTML=(AREA_PROJECTS[area]||[]).map(p=>`<option>${p}</option>`).join('')}
