    const hdr=a[2]||[], drCol=hdr.findIndex(x=>String(x).trim()==='DR'), bizCol=hdr.findIndex(x=>String(x).trim()==='業務名'), payCol=hdr.findIndex(x=>String(x).trim()==='DR金額');
