async function load(){
  // V4.9.1: 公式の売上・単価データは毎回JSONから読み、古いlocalStorageの空データで上書きされないようにする。
  const r=await fetch('./jarvis-v4-data.json?ts='+Date.now(),{cache:'no-store'});
  if(!r.ok)throw new Error('jarvis-v4-data.json load failed: '+r.status);
  DATA=await r.json();
  const a=localStorage.getItem(ATT_KEY);
  ATT=cleanAttendance(a?JSON.parse(a):legacyAttendance());
  localStorage.setItem(ATT_KEY,JSON.stringify(ATT));
  populateForm();
  seedAugustShift();
  syncTodayFromAttendance();
  DATA.version='4.9.9';
  DATA.shift_version='2026-08-28-v4914-mishima-work-integrated';
  DATA.actuals_version='2026-08-28-v499-safe-voice';
  localStorage.setItem(STORAGE_KEY,JSON.stringify(DATA));
  initShiftControls();
  render();
  renderDrivers();
  renderShiftMatrix();
  try{ await initWorkbook(); }catch(e){ console.warn('Workbook init skipped:',e); const ws=document.getElementById('workbookStatus'); if(ws)ws.textContent='配送管理表は画面起動後に利用できます'; }
}
load().catch(e=>{console.error(e);const el=document.getElementById('pageSub');if(el)el.textContent='DATA LINK ERROR: '+e.message});
